use std::fs::File;
use std::io::{self, BufRead, BufReader, Read};
use std::path::Path;

pub fn promedio_columna_csv<P: AsRef<Path>>(
    path: P,
    columna: usize,
    tiene_encabezado: bool,
) -> io::Result<f64> {
    let file = File::open(path)?;
    promedio_columna_reader(BufReader::new(file), columna, tiene_encabezado)
}

pub fn promedio_columna_reader<R: Read>(
    reader: R,
    columna: usize,
    tiene_encabezado: bool,
) -> io::Result<f64> {
    let mut br = BufReader::new(reader);

    let mut suma = 0.0_f64;
    let mut cuenta: u64 = 0;
    let mut fila: u64 = 1;

    let mut col: usize = 0;
    let mut in_quotes = false;
    let mut quote_pending = false;
    let mut field_started = false;
    let mut row_has_bytes = false;
    let mut header_pending = tiene_encabezado;
    let mut skip_lf = false;

    let mut target = Vec::<u8>::new();

    loop {
        let chunk = br.fill_buf()?;
        if chunk.is_empty() {
            break;
        }

        let mut consumed = 0;

        for &b in chunk {
            consumed += 1;

            // Para CRLF: si ya terminamos fila con '\r', ignoramos el '\n' siguiente.
            if skip_lf {
                if b == b'\n' {
                    skip_lf = false;
                    continue;
                }
                skip_lf = false;
            }

            if in_quotes {
                if quote_pending {
                    if b == b'"' {
                        // Comilla escapada: ""
                        if col == columna && !header_pending {
                            target.push(b'"');
                        }
                        quote_pending = false;
                        continue;
                    } else {
                        // Se cerró el campo entrecomillado; procesamos este byte afuera.
                        in_quotes = false;
                        quote_pending = false;
                    }
                } else {
                    if b == b'"' {
                        quote_pending = true;
                    } else if col == columna && !header_pending {
                        target.push(b);
                    }
                    continue;
                }
            }

            // Fuera de comillas (o recién cerrada una comilla).
