                b',' => {
                    agregar_si_corresponde(
                        &target,
                        col,
                        columna,
                        fila,
                        header_pending,
                        &mut suma,
                        &mut cuenta,
                    )?;

                    col += 1;
                    field_started = false;
                    row_has_bytes = true;
                    target.clear();
                }

                b'\n' => {
                    if row_has_bytes || field_started || col > 0 {
                        agregar_si_corresponde(
                            &target,
                            col,
                            columna,
                            fila,
                            header_pending,
                            &mut suma,
                            &mut cuenta,
                        )?;

                        col += 1;

                        if !header_pending && col <= columna {
                            return Err(io::Error::new(
                                io::ErrorKind::InvalidData,
                                format!("fila {}: no existe la columna {}", fila, columna),
                            ));
                        }

