use std::error::Error;
use std::fmt;
use std::fs::File;
use std::io::{self, Read};

#[derive(Debug)]
pub enum CsvAverageError {
    Io(io::Error),
    MissingColumn {
        record: u64,
        column: usize,
        found: usize,
    },
    InvalidNumber {
        record: u64,
        column: usize,
        value: String,
    },
}

impl fmt::Display for CsvAverageError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Io(e) => write!(f, "error de E/S: {e}"),
            Self::MissingColumn {
                record,
                column,
                found,
            } => write!(
                f,
                "registro {record}: se pidió la columna {column} (base 0), pero solo hay {found} columnas"
            ),
            Self::InvalidNumber {
                record,
                column,
                value,
            } => write!(
                f,
                "registro {record}, columna {column}: valor numérico inválido {value:?}"
            ),
        }
    }
}

impl Error for CsvAverageError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Io(e) => Some(e),
            _ => None,
        }
    }
}

impl From<io::Error> for CsvAverageError {
    fn from(e: io::Error) -> Self {
        Self::Io(e)
    }
}

